#target photoshop
app.displayDialogs = DialogModes.NO;
app.preferences.rulerUnits = Units.PIXELS;
var doc = app.open(new File("C:/in/shot.psd"));
doc.resizeImage(UnitValue(1920, "px"), null, 72, ResampleMethod.BICUBICSHARPER);
doc.flatten();
var opts = new JPEGSaveOptions();
opts.quality = 10;
doc.saveAs(new File("C:/out/shot.jpg"), opts, true, Extension.LOWERCASE);
doc.close(SaveOptions.DONOTSAVECHANGES);

var idFill = stringIDToTypeID("fill");
var d = new ActionDescriptor();
d.putEnumerated(stringIDToTypeID("using"),
                stringIDToTypeID("fillContents"),
                stringIDToTypeID("foregroundColor"));
d.putUnitDouble(stringIDToTypeID("opacity"), stringIDToTypeID("percentUnit"), 100);
executeAction(idFill, d, DialogModes.NO);

const { app, core, action } = require("photoshop");
async function run() {
  const doc = app.activeDocument;
  await action.batchPlay([{
    _obj: "gaussianBlur",
    radius: { _unit: "pixelsUnit", _value: 4 }
  }], {});
  doc.activeLayers[0].name = "blurred";
}
await core.executeAsModal(run, { commandName: "Blur layer" });
